// AttributeComment is a comment (either single-line `// ...` or multi-line
// `/* ... */`) that appears within the attribute list of an HTML element.
type AttributeComment struct {
	// Comment is the text content of the comment (everything after "//" or
	// between "/*" and "*/").
	Comment string
	// Multiline is true for `/* */` block comments, and false for `//`
	// single-line comments.
	Multiline bool
	Range     Range
}

func (c *AttributeComment) String() string {
	if c.Multiline {
		return "/*" + c.Comment + "*/"
	}
	return "//" + c.Comment
}

func (c *AttributeComment) Write(w io.Writer, indent int) error {
	if c.Multiline {
		return writeIndent(w, indent, "/*", c.Comment, "*/")
	}
	return writeIndent(w, indent, "//", c.Comment)
}

func (c *AttributeComment) Visit(v Visitor) error {
	return v.VisitAttributeComment(c)
}

